CREATE TYPE "application_status" AS ENUM (
  'interested',
  'writing',
  'submitted',
  'in_progress',
  'closed'
);

CREATE TYPE "deadline_kind" AS ENUM (
  'fixed',
  'rolling',
  'until_filled',
  'always_open'
);

CREATE TABLE "users" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar UNIQUE NOT NULL,
  "password_hash" varchar,
  "name" varchar NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "timezone" varchar NOT NULL DEFAULT 'Asia/Seoul'
);

CREATE TABLE "oauth_accounts" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "provider" varchar NOT NULL,
  "provider_user_id" varchar NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "applications" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "company" text NOT NULL,
  "role" text NOT NULL,
  "deadline_kind" deadline_kind,
  "deadline_date" date,
  "deadline_time" time,
  "deadline_timezone" varchar NOT NULL DEFAULT 'Asia/Seoul',
  "source_url" text,
  "source_text" text,
  "source_image_key" text,
  "posting_position_id" bigint,
  "status" application_status NOT NULL DEFAULT 'interested',
  "current_stage_id" bigint,
  "outcome_option_id" bigint,
  "outcome_stage_name" text
);

CREATE TABLE "application_sections" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "application_id" bigint NOT NULL,
  "title" text NOT NULL,
  "body" text NOT NULL,
  "position" integer NOT NULL
);

CREATE TABLE "application_stages" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "application_id" bigint NOT NULL,
  "name" text NOT NULL,
  "position" integer NOT NULL
);

CREATE TABLE "application_outcome_options" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "name" varchar NOT NULL,
  "color" varchar,
  "position" integer NOT NULL,
  "archived_at" timestamptz
);

CREATE TABLE "essay_questions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "application_id" bigint NOT NULL,
  "prompt" text NOT NULL,
  "char_limit" integer CHECK ("char_limit" BETWEEN 1 AND 100000),
  "position" integer NOT NULL
);

CREATE TABLE "writing_versions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "question_id" bigint NOT NULL,
  "name" varchar NOT NULL,
  "draft_body" text NOT NULL DEFAULT ''
);

CREATE TABLE "snapshots" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "question_id" bigint NOT NULL,
  "version_id" bigint NOT NULL,
  "title" text,
  "description" text,
  "body" text NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "submission_answers" (
  "question_id" bigint PRIMARY KEY,
  "body" text NOT NULL,
  "updated_at" timestamptz NOT NULL DEFAULT (now())
);

CREATE TABLE "snapshot_parents" (
  "question_id" bigint NOT NULL,
  "child_snapshot_id" bigint NOT NULL,
  "parent_snapshot_id" bigint NOT NULL,
  PRIMARY KEY ("child_snapshot_id", "parent_snapshot_id")
);

CREATE INDEX ON "oauth_accounts" ("user_id");

CREATE UNIQUE INDEX ON "oauth_accounts" ("provider", "provider_user_id");

CREATE INDEX ON "applications" ("user_id");

CREATE UNIQUE INDEX ON "application_sections" ("application_id", "position");

ALTER TABLE "application_stages"
  ADD CONSTRAINT "application_stages_application_id_position_key"
  UNIQUE ("application_id", "position") DEFERRABLE INITIALLY IMMEDIATE;

CREATE UNIQUE INDEX ON "application_stages" ("application_id", "id");

CREATE UNIQUE INDEX ON "application_outcome_options" ("user_id", "id");

CREATE INDEX ON "application_outcome_options" ("user_id", "position");

CREATE UNIQUE INDEX ON "essay_questions" ("application_id", "position");

CREATE UNIQUE INDEX ON "writing_versions" ("question_id", "id");

CREATE UNIQUE INDEX ON "snapshots" ("question_id", "id");

CREATE INDEX ON "snapshot_parents" ("parent_snapshot_id");

ALTER TABLE "oauth_accounts" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "applications" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "application_outcome_options" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "application_sections" ADD FOREIGN KEY ("application_id") REFERENCES "applications" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "application_stages" ADD FOREIGN KEY ("application_id") REFERENCES "applications" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "essay_questions" ADD FOREIGN KEY ("application_id") REFERENCES "applications" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "applications" ADD FOREIGN KEY ("id", "current_stage_id") REFERENCES "application_stages" ("application_id", "id") ON DELETE SET NULL ("current_stage_id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "applications" ADD FOREIGN KEY ("user_id", "outcome_option_id") REFERENCES "application_outcome_options" ("user_id", "id") ON DELETE NO ACTION DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "writing_versions" ADD FOREIGN KEY ("question_id") REFERENCES "essay_questions" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "snapshots" ADD FOREIGN KEY ("question_id", "version_id") REFERENCES "writing_versions" ("question_id", "id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "submission_answers" ADD FOREIGN KEY ("question_id") REFERENCES "essay_questions" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "snapshot_parents" ADD FOREIGN KEY ("question_id", "child_snapshot_id") REFERENCES "snapshots" ("question_id", "id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "snapshot_parents" ADD FOREIGN KEY ("question_id", "parent_snapshot_id") REFERENCES "snapshots" ("question_id", "id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

CREATE TABLE shared_posting_question_sets (
    id uuid PRIMARY KEY,
    posting_key char(64) NOT NULL,
    posting_url text NOT NULL,
    role_key text NOT NULL,
    questions jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    UNIQUE (posting_key, role_key)
);

CREATE TABLE shared_posting_question_reports (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    question_set_id uuid NOT NULL REFERENCES shared_posting_question_sets (id),
    proposed_questions jsonb NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX shared_posting_question_reports_set_idx ON shared_posting_question_reports (question_set_id);

CREATE TABLE postings (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  source_key char(64) NOT NULL UNIQUE,
  canonical_url text NOT NULL,
  canonical_url_key char(64) NOT NULL,
  company text NOT NULL,
  source_text text,
  common_payload jsonb NOT NULL CHECK (jsonb_typeof(common_payload) = 'object'),
  input_hash char(64) NOT NULL,
  extractor_version text NOT NULL,
  last_checked_at timestamptz NOT NULL,
  refresh_after timestamptz
);

CREATE INDEX ON postings (canonical_url_key);

CREATE TABLE posting_positions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  posting_id bigint NOT NULL REFERENCES postings (id) ON DELETE RESTRICT,
  position_key text NOT NULL,
  role text NOT NULL,
  position_payload jsonb NOT NULL CHECK (jsonb_typeof(position_payload) = 'object'),
  UNIQUE (posting_id, position_key)
);

CREATE INDEX applications_posting_position_idx ON applications (posting_position_id);

ALTER TABLE applications ADD CONSTRAINT applications_posting_position_fk
  FOREIGN KEY (posting_position_id) REFERENCES posting_positions (id) ON DELETE RESTRICT;

CREATE TABLE user_essay_template_items (
  user_id bigint NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  position integer NOT NULL CHECK (position BETWEEN 1 AND 30),
  prompt text NOT NULL CHECK (char_length(btrim(prompt)) BETWEEN 1 AND 2000),
  draft_body text NOT NULL CHECK (char_length(draft_body) <= 20000),
  char_limit integer CHECK (char_limit BETWEEN 1 AND 100000),
  PRIMARY KEY (user_id, position)
);
